using CubeSolverPro.Core.Data;
namespace CubeSolverPro.Core.Algorithms;
public sealed record AlgorithmCase(string Id,string Name,string Group,IReadOnlyList<string> Algs); public sealed record AlgorithmSet(string Id,string Name,IReadOnlyList<AlgorithmCase> Cases);
public static class DrillSelection {public static double Weight(TrainerStat? stat,double median){if(stat is null||stat.Attempts==0)return 8;double w=stat.Status=="known"?1:3;if(stat.RecentMs.Count>0&&median>0)w*=Math.Min(3,Math.Max(.5,stat.RecentMs.Average()/median));if(stat.Attempts<3)w*=2;if(stat.Dnfs>0)w*=1+Math.Min(1,(double)stat.Dnfs/Math.Max(1,stat.Attempts));if(stat.Starred)w*=2;return w;}public static AlgorithmCase? Pick(IReadOnlyList<AlgorithmCase> cases,Func<AlgorithmCase,TrainerStat?> statOf,Random? random=null,string? avoidId=null){var pool=cases.Count>1&&avoidId!=null?cases.Where(x=>x.Id!=avoidId).ToArray():cases.ToArray();if(pool.Length==0)return null;var values=pool.Select(statOf).Where(x=>x?.RecentMs.Count>0).Select(x=>x!.RecentMs.Average()).Order().ToArray();var median=values.Length==0?0:values[values.Length/2];var weights=pool.Select(x=>Weight(statOf(x),median)).ToArray();var target=(random??Random.Shared).NextDouble()*weights.Sum();for(var i=0;i<pool.Length;i++)if((target-=weights[i])<=0)return pool[i];return pool[^1];}}
